def _browser_workflow_scope_runtime_checklist(
    *,
    task_state_policy: Mapping[str, object],
    browser_workflows: Sequence[Mapping[str, object]],
) -> dict[str, object]:
    workflow_rows = [dict(row) for row in browser_workflows]
    workflow_kinds = [
        str(row.get("workflow_kind") or "").strip()
        for row in workflow_rows
        if str(row.get("workflow_kind") or "").strip()
    ]
    mutable_workflow_kinds: list[str] = []
    workflows_missing_target_token: list[str] = []
    workflows_missing_write_scope: list[str] = []
    workflows_missing_session_guard: list[str] = []
    for row in workflow_rows:
        workflow_kind = str(row.get("workflow_kind") or "").strip() or "unknown"
        if not bool(row.get("server_mutation")):
            continue
        mutable_workflow_kinds.append(workflow_kind)
        write_scope = str(row.get("write_scope") or "").strip()
        if not write_scope:
            workflows_missing_write_scope.append(workflow_kind)
        write_contract = row.get("write_contract") if isinstance(row.get("write_contract"), Mapping) else {}
        if str(write_contract.get("guard") or "") != "session_for_user":
            workflows_missing_session_guard.append(workflow_kind)
        payload_fields = {
            str(field)
            for field in (
                write_contract.get("payload_fields")
                if isinstance(write_contract.get("payload_fields"), list)
                else []
            )
            if str(field or "").strip()
        }
        required_fields = {
            str(field)
            for field in (
                write_contract.get("required_fields")
                if isinstance(write_contract.get("required_fields"), list)
                else []
            )
            if str(field or "").strip()
        }
        if "target_token" not in payload_fields or "target_token" not in required_fields:
            workflows_missing_target_token.append(workflow_kind)
    absolute_navigation_out_of_scope = str(
        task_state_policy.get("absolute_navigation_out_of_scope") or ""
    )
    browser_mutation_target_selectors = str(
        task_state_policy.get("browser_mutation_target_selectors") or ""
    )
    browser_mutation_target_token = str(task_state_policy.get("browser_mutation_target_token") or "")
    absolute_navigation_out_of_scope_rejects = absolute_navigation_out_of_scope == "reject_nav_error"
    browser_mutation_targets_server_owned = (
        browser_mutation_target_selectors == "server_owned_reject_client_fields"
    )
    current_target_token_required = browser_mutation_target_token == "required_current_target_token"
    mutable_workflows_require_target_token = not workflows_missing_target_token
    mutable_workflows_session_guarded = not workflows_missing_session_guard
    mutable_workflows_have_write_scope = not workflows_missing_write_scope
    target_scope_enforced = (
        absolute_navigation_out_of_scope_rejects
        and browser_mutation_targets_server_owned
        and current_target_token_required
        and mutable_workflows_require_target_token
        and mutable_workflows_session_guarded
        and mutable_workflows_have_write_scope
        and bool(workflow_kinds)
    )
    return {
        "schema": "palette.web_labeling_browser_workflow_scope_runtime_checklist.v1",
        "ready": target_scope_enforced,
        "supported_browser_workflow_kinds": workflow_kinds,
        "browser_workflow_count": len(workflow_kinds),
        "mutable_browser_workflow_kinds": mutable_workflow_kinds,
        "mutable_browser_workflow_count": len(mutable_workflow_kinds),
        "absolute_navigation_out_of_scope": absolute_navigation_out_of_scope,
        "absolute_navigation_out_of_scope_rejects": absolute_navigation_out_of_scope_rejects,
        "browser_mutation_target_selectors": browser_mutation_target_selectors,
        "browser_mutation_targets_server_owned": browser_mutation_targets_server_owned,
        "browser_mutation_target_token": browser_mutation_target_token,
        "current_target_token_required": current_target_token_required,
        "mutable_workflows_require_target_token": mutable_workflows_require_target_token,
        "workflows_missing_target_token": workflows_missing_target_token,
        "mutable_workflows_session_guarded": mutable_workflows_session_guarded,
        "workflows_missing_session_guard": workflows_missing_session_guard,
        "mutable_workflows_have_write_scope": mutable_workflows_have_write_scope,
        "workflows_missing_write_scope": workflows_missing_write_scope,
        "browser_direct_target_selection_rejected": browser_mutation_targets_server_owned,
        "target_selector_fields_rejected": list(BROWSER_MUTATION_TARGET_SELECTOR_KEYS),
        "target_indices_components_labels_frames_inside_task_scope": target_scope_enforced,
        "labeler_visible_scope": "assigned_recordings_for_resolved_user",
        "data_plane_mutation_scope": "current_guarded_session_task_target",
    }


def _iter_zarr_path_values(value: object) -> Iterable[tuple[str, str]]:
    if isinstance(value, Mapping):
        for key, child in value.items():
            key_text = str(key)
            if key_text in ZARR_BACKUP_PATH_KEYS and isinstance(child, str) and child.strip():
                yield key_text, child.strip()
            yield from _iter_zarr_path_values(child)
        return
    if isinstance(value, list):
        for child in value:
            yield from _iter_zarr_path_values(child)


def _zarr_backup_role_for_key(key: str, task: Mapping[str, object]) -> str:
    workflow_kind = str(task.get("workflow_kind") or "")
    zarr_use = str(task.get("zarr_use") or "")
    if "training" in key:
        return "training"
    if "analysis" in key:
        return "analysis"
    if zarr_use:
        return zarr_use
    if workflow_kind == "detect_analysis":
        return "analysis"
    return "unspecified"


def _zarr_backup_plan(
    *,
    store: LabelingStore,
    store_path: Path,
    recording_id: str | None = None,
    user: str | None = None,
    include_completed: bool = True,
    include_inactive: bool = False,
) -> dict[str, object]:
    generated_at_utc = datetime.now(timezone.utc).isoformat()
    tasks = store.list_tasks(recording_id=recording_id, assignee_user=user, include_completed=include_completed)
    if not include_inactive:
        tasks = [task for task in tasks if str(task.get("assignment_status") or "") == "active"]
    grouped: dict[str, dict[str, object]] = {}
    missing_path_tasks: list[dict[str, object]] = []
    for task in tasks:
        scope = task.get("scope") if isinstance(task.get("scope"), Mapping) else {}
        paths = list(_iter_zarr_path_values(scope))
        if not paths:
            missing_path_tasks.append(
                {
                    "task_id": task.get("task_id"),
                    "recording_id": task.get("recording_id"),
                    "assignee_user": task.get("assignee_user"),
                    "workflow_kind": task.get("workflow_kind"),
                    "zarr_use": task.get("zarr_use"),
                    "details": "Task scope does not expose a zarr path for backup planning.",
                }
            )
            continue
        registry_paths = sorted(
            {
                str(value).strip()
                for key, value in scope.items()
                if str(key) == "registry_path" and isinstance(value, str) and value.strip()
            }
        )
        for key, zarr_path in paths:
            role = _zarr_backup_role_for_key(key, task)
            group_key = json.dumps([zarr_path, role], separators=(",", ":"), sort_keys=True)
            target = grouped.setdefault(
                group_key,
                {
                    "zarr_path": zarr_path,
                    "zarr_role": role,
                    "backup_required": role in {"training", "analysis", "unspecified"},
                    "copy_before_labeling": True,
                    "restore_requires_paused_assignment": True,
                    "recording_ids": set(),
                    "assignee_users": set(),
                    "task_ids": set(),
                    "workflow_kinds": set(),
                    "dataset_ids": set(),
                    "zarr_uses": set(),
                    "stage_groups": set(),
                    "run_names": set(),
                    "component_names": set(),
                    "registry_paths": set(),
                    "source_scope_keys": set(),
                },
            )
            for target_key, task_key in (
                ("recording_ids", "recording_id"),
                ("assignee_users", "assignee_user"),
                ("task_ids", "task_id"),
                ("workflow_kinds", "workflow_kind"),
                ("dataset_ids", "dataset_id"),
                ("zarr_uses", "zarr_use"),
                ("stage_groups", "stage_group"),
                ("run_names", "run_name"),
                ("component_names", "component_name"),
            ):
                value = str(task.get(task_key) or "").strip()
                if value:
                    target[target_key].add(value)  # type: ignore[union-attr]
            for registry_path in registry_paths:
                target["registry_paths"].add(registry_path)  # type: ignore[union-attr]
            target["source_scope_keys"].add(key)  # type: ignore[union-attr]
    zarr_targets: list[dict[str, object]] = []
    for target in grouped.values():
        normalized = dict(target)
        for key in (
            "recording_ids",
            "assignee_users",
            "task_ids",
            "workflow_kinds",
            "dataset_ids",
            "zarr_uses",
            "stage_groups",
            "run_names",
            "component_names",
            "registry_paths",
            "source_scope_keys",
        ):
            values = normalized.get(key, set())
            normalized[key] = sorted(str(value) for value in values) if isinstance(values, set) else []
        normalized["backup_manifest_template"] = {
            "backup_schema": "palette.web_labeling_zarr_backup.v1",
            "created_utc": generated_at_utc,
            "reason": "before web labeling batch",
            "zarr_path": normalized["zarr_path"],
            "zarr_role": normalized["zarr_role"],
            "recording_ids": normalized["recording_ids"],
            "dataset_ids": normalized["dataset_ids"],
            "task_ids": normalized["task_ids"],
            "registry_paths": normalized["registry_paths"],
        }
        zarr_targets.append(normalized)
    zarr_targets.sort(key=lambda row: (str(row.get("zarr_role") or ""), str(row.get("zarr_path") or "")))
    zarr_targets_by_role: dict[str, int] = {}
    backup_required_targets_by_role: dict[str, int] = {}
    for target in zarr_targets:
        role = str(target.get("zarr_role") or "unspecified")
        zarr_targets_by_role[role] = zarr_targets_by_role.get(role, 0) + 1
        if bool(target.get("backup_required")):
            backup_required_targets_by_role[role] = backup_required_targets_by_role.get(role, 0) + 1
    warnings = [{"code": "task_missing_zarr_path_for_backup_plan", **task} for task in missing_path_tasks]
    return {
        "ok": True,
        "schema": "palette.web_labeling_zarr_backup_plan.v1",
        "generated_at_utc": generated_at_utc,
        "store_path": str(store_path),
        "filters": {
            "recording_id": recording_id,
            "user": user,
            "include_completed": bool(include_completed),
            "include_inactive": bool(include_inactive),
        },
        "policy": _zarr_backup_policy(),
        "counts": {
            "tasks_examined": len(tasks),
            "tasks_missing_zarr_path": len(missing_path_tasks),
            "zarr_targets": len(zarr_targets),
            "backup_required_targets": sum(1 for target in zarr_targets if bool(target.get("backup_required"))),
            "unique_zarr_paths": len({str(target.get("zarr_path") or "") for target in zarr_targets}),
            "zarr_targets_by_role": dict(sorted(zarr_targets_by_role.items())),
            "backup_required_targets_by_role": dict(sorted(backup_required_targets_by_role.items())),
        },
        "warning_count": len(warnings),
        "warning_codes": sorted({str(warning.get("code") or "") for warning in warnings}),
        "warnings": warnings,
        "zarr_targets": zarr_targets,
    }


def _zarr_backup_evidence_template(plan: Mapping[str, object]) -> dict[str, object]:
    generated_at_utc = datetime.now(timezone.utc).isoformat()
    targets = plan.get("zarr_targets") if isinstance(plan.get("zarr_targets"), list) else []
    evidence_targets: list[dict[str, object]] = []
    for idx, target in enumerate(targets):
        if not isinstance(target, Mapping) or not bool(target.get("backup_required")):
            continue
        evidence_targets.append(
            {
                "target_index": idx,
                "status": "pending_operator_confirmation",
                "zarr_path": str(target.get("zarr_path") or ""),
                "zarr_role": str(target.get("zarr_role") or ""),
                "recording_ids": list(target.get("recording_ids") or [])
                if isinstance(target.get("recording_ids"), list)
                else [],
                "dataset_ids": list(target.get("dataset_ids") or [])
                if isinstance(target.get("dataset_ids"), list)
                else [],
                "task_ids": list(target.get("task_ids") or [])
                if isinstance(target.get("task_ids"), list)
                else [],
                "registry_paths": list(target.get("registry_paths") or [])
                if isinstance(target.get("registry_paths"), list)
                else [],
                "backup_required": True,
                "copy_before_labeling": bool(target.get("copy_before_labeling")),
                "restore_requires_paused_assignment": bool(
                    target.get("restore_requires_paused_assignment")
                ),
                "backup_execution_manifest_path": "",
                "backup_manifest_path": "",
                "backup_destination": "",
                "backup_created_at_utc": "",
                "backup_verified_at_utc": "",
                "restore_test_result": "",
                "operator": "",
                "operator_approved_at_utc": "",
                "notes": "",
            }
        )
    return {
        "ok": True,
        "schema": "palette.web_labeling_zarr_backup_evidence_template.v1",
        "generated_at_utc": generated_at_utc,
        "operator_only": True,
        "labelers_do_not_receive": True,
        "source_plan_schema": str(plan.get("schema") or ""),
        "source_plan_generated_at_utc": str(plan.get("generated_at_utc") or ""),
        "store_path": str(plan.get("store_path") or ""),
        "policy": _zarr_backup_policy(),
        "instructions": [
            "Fill one row per backup-required mutable Zarr target before broad labeler link sharing.",
            "Record backup_manifest_path or backup_destination only in operator-controlled storage; do not send this file to labelers.",
            "Set status to operator_approved only after the backup or known-good regeneration path is verified.",
            "Pause or unassign affected recordings before any restore from this backup evidence.",
        ],
        "counts": {
            "backup_required_targets": len(evidence_targets),
            "pending_operator_confirmation": len(evidence_targets),
            "operator_approved": 0,
        },
        "targets": evidence_targets,
    }



